+  if (expects(after) < expects(before)) return `removes an expect (${expects(before)} -> ${expects(after)})`;
+  if (skips(after) > skips(before)) return "adds test.skip or test.fixme";
+  for (const key of Object.keys(TOLERANCES)) {
+    const [was, now] = [tolerance(before, key), tolerance(after, key)];
+    if (now > was) return `raises ${key} (${was} -> ${now})`;
+  }
+  const left = matchers(after);
+  for (const m of matchers(before)) {
+    const i = left.indexOf(m);
+    if (i < 0) return `changes an expected value: ${m}`;
+    left.splice(i, 1);
+  }
+}
+
+const stdin = await Bun.stdin.text();
+let changes: Change[];
+try { changes = fromHook(JSON.parse(stdin)); } catch { changes = fromDiff(stdin); }
+
+for (const change of changes.filter((c) => judged(c.file))) {
+  const reason = weakens(change);
+  if (reason) {
+    console.error(`guard: ${change.file}: ${reason}`);
+    process.exit(2);
+  }
+}
+process.exit(0);

