  const lines = diff.split("\n");
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index];
    const next = lines[index + 1] ?? "";
    const previous = lines[index - 1] ?? "";
    // `--- a/x` followed by `+++ b/x` starts a new file; a removed line starting with `--` does not.
    if (line.startsWith("--- ") && next.startsWith("+++ ")) {
      continue;
    }
    if (line.startsWith("+++ ") && previous.startsWith("--- ")) {
      current = { file: fileFromHeaders(previous, line), before: "", after: "" };
      changes.push(current);
      continue;
    }
    if (current !== undefined && !isDiffMetadata(line)) {
      addHunkLine(current, line);
    }
  }
  return changes;
}

// ---- Reading standard input ----

// Hook payloads are JSON objects; anything that does not parse as one is treated as a diff.
function parseHook(input: string): HookInput | undefined {
  try {
    const parsed: unknown = JSON.parse(input);
    if (typeof parsed === "object" && parsed !== null) {
      return parsed;
    }
  } catch {
