  const input = await Bun.stdin.text();
  for (const change of readChanges(input)) {
    if (!isJudged(change.file)) {
      continue;
    }
    const reason = findWeakening(change);
    if (reason !== undefined) {
      console.error(`guard: ${change.file}: ${reason}`);
