+import { existsSync, readFileSync } from "node:fs";
+
+type Change = { file: string; before: string; after: string };
+
+const judged = (file: string) => file.endsWith(".spec.ts") || /(^|\/)playwright\.config\.ts$/.test(file);
+
+function fromHook(input: any): Change[] {
+  const t = input.tool_input ?? {};
+  const file: string = t.file_path ?? "";
+  if (input.tool_name === "Write") {
+    return [{ file, before: existsSync(file) ? readFileSync(file, "utf8") : "", after: t.content ?? "" }];
+  }
+  const edits = t.edits ?? [t];
+  return edits.map((e: any) => ({ file, before: e.old_string ?? "", after: e.new_string ?? "" }));
+}
+
+function fromDiff(diff: string): Change[] {
+  const changes: Change[] = [];
+  let cur: { file: string; before: string[]; after: string[] } | undefined;
+  const lines = diff.split("\n");
+  lines.forEach((line, i) => {
+    if (line.startsWith("--- ") && lines[i + 1]?.startsWith("+++ ")) return;
+    if (line.startsWith("+++ ") && lines[i - 1]?.startsWith("--- ")) {
+      const path = (s: string) => s.slice(4).split("\t")[0].replace(/^[ab]\//, "");
+      const file = line.endsWith("/dev/null") ? path(lines[i - 1]) : path(line);
+      cur = { file, before: [], after: [] };
+      changes.push(cur as any);
+      return;
+    }
+    if (!cur || line.startsWith("diff ") || line.startsWith("@@") || line.startsWith("\\")) return;
+    const [mark, text] = [line[0], line.slice(1)];
+    if (mark === " " || mark === undefined) cur.before.push(text), cur.after.push(text);
+    else if (mark === "-") cur.before.push(text);
+    else if (mark === "+") cur.after.push(text);
+  });
+  return changes.map((c: any) => ({ file: c.file, before: c.before.join("\n"), after: c.after.join("\n") }));
+}
+
+const count = (s: string, re: RegExp) => s.match(re)?.length ?? 0;
+const expects = (s: string) => count(s, /\bexpect(\.\w+)*\s*\(/g);
+const skips = (s: string) => count(s, /\btest(\.describe)?\.(skip|fixme)\b/g);
+
+function matchers(s: string): string[] {
+  const out: string[] = [];
+  for (const m of s.matchAll(/(\.not)?\.(to[A-Z]\w*)\s*\(/g)) {
+    let depth = 1, i = m.index! + m[0].length, quote = "";
+    const start = i;
+    for (; i < s.length && depth > 0; i++) {
+      const c = s[i];
+      if (quote) { if (c === "\\") i++; else if (c === quote) quote = ""; }
+      else if (`"'\``.includes(c)) quote = c;
+      else if (c === "(") depth++;
+      else if (c === ")") depth--;
+    }
+    const args = s.slice(start, depth ? i : i - 1).replace(/\s+/g, " ").replace(/,?\s*$/, "").trim();
+    out.push(`${m[1] ?? ""}.${m[2]}(${args})`);
+  }
+  return out;
+}
+
+const TOLERANCES: Record<string, number> = { maxDiffPixels: 0, maxDiffPixelRatio: 0, threshold: 0.2, retries: 0 };
+function tolerance(s: string, key: string): number {
+  const values = [...s.matchAll(new RegExp(`\\b${key}\\s*:\\s*([^,}\\n]+)`, "g"))]
+    .flatMap((m) => m[1].match(/\d*\.?\d+/g) ?? []).map(Number);
+  return values.length ? Math.max(...values) : TOLERANCES[key];
+}
+
+function weakens({ before, after }: Change): string | undefined {
+  if (expects(after) < expects(before)) return `removes an expect (${expects(before)} -> ${expects(after)})`;
+  if (skips(after) > skips(before)) return "adds test.skip or test.fixme";
+  for (const key of Object.keys(TOLERANCES)) {
+    const [was, now] = [tolerance(before, key), tolerance(after, key)];
+    if (now > was) return `raises ${key} (${was} -> ${now})`;
+  }
+  const left = matchers(after);
+  for (const m of matchers(before)) {
+    const i = left.indexOf(m);
+    if (i < 0) return `changes an expected value: ${m}`;
+    left.splice(i, 1);
+  }
+}
+
+const stdin = await Bun.stdin.text();
+let changes: Change[];
+try { changes = fromHook(JSON.parse(stdin)); } catch { changes = fromDiff(stdin); }
+
+for (const change of changes.filter((c) => judged(c.file))) {
+  const reason = weakens(change);
+  if (reason) {
+    console.error(`guard: ${change.file}: ${reason}`);
+    process.exit(2);
+  }
+}
+process.exit(0);

