const diff = (file: string, body: string) => `--- a/${file}\n+++ b/${file}\n@@ -1,9 +1,9 @@\n${body}\n`;
const hook = (tool_name: string, tool_input: object) => JSON.stringify({ tool_name, tool_input });

const cases: [number, string, string | Promise<string>][] = [
  [2, "example: removes an expect", example("removes-an-expect")],
  [0, "example: changes a locator", example("changes-a-locator")],
  [2, "changes a value", diff("tests/b.spec.ts", `   test("x", async () => {\n-    await expect(t).toHaveText("$12.40");\n+    await expect(t).toHaveText("$12.41");\n   });`)],
  [2, "adds test.skip", diff("tests/b.spec.ts", `-  test("x", async () => {\n+  test.skip("x", async () => {\n     await expect(t).toHaveText("$12.40");`)],
  [2, "adds test.fixme", diff("tests/b.spec.ts", `+  test.fixme();\n   test("x", async () => {`)],
  [2, "drops .not", diff("tests/b.spec.ts", `-    await expect(b).not.toBeVisible();\n+    await expect(b).toBeVisible();`)],
  [2, "raises retries", diff("playwright.config.ts", ` export default defineConfig({\n-  retries: 0,\n+  retries: process.env.CI ? 3 : 0,\n });`)],
  [2, "adds retries", diff("playwright.config.ts", ` export default defineConfig({\n+  retries: 2,\n });`)],
  [2, "raises threshold", diff("playwright.config.ts", `-  expect: { toHaveScreenshot: { threshold: 0.2 } },\n+  expect: { toHaveScreenshot: { threshold: 0.5 } },`)],
  [2, "raises maxDiffPixelRatio", diff("playwright.config.ts", `-  expect: { toHaveScreenshot: { maxDiffPixelRatio: 0.01 } },\n+  expect: { toHaveScreenshot: { maxDiffPixelRatio: 0.1 } },`)],
  [2, "raises maxDiffPixels in a spec", diff("tests/look.spec.ts", `-    await expect(page).toHaveScreenshot({ maxDiffPixels: 10 });\n+    await expect(page).toHaveScreenshot({ maxDiffPixels: 100 });`)],
  [0, "lowers retries", diff("playwright.config.ts", `-  retries: 2,\n+  retries: 0,`)],
  [0, "adds an expect", diff("tests/b.spec.ts", `     await expect(t).toHaveText("$12.40");\n+    await expect(w).toHaveText("750 g");`)],
  [0, "renames a test", diff("tests/b.spec.ts", `-  test("old name", async () => {\n+  test("clearer name", async () => {\n     await expect(t).toHaveText("$12.40");`)],
  [0, "locator change, multiline matcher with ( in a string", diff("tests/s.spec.ts", `-    await expect(page.getByTestId("blocked")).toHaveText(\n+    await expect(page.getByRole("alert")).toHaveText(\n       "Book a slot (to check out).",\n     );`)],
  [0, "not a test file", diff("src/app.ts", `-expect(x).toBe(1);`)],
  [2, "Edit hook: removes an expect", hook("Edit", { file_path: "/x/tests/b.spec.ts", old_string: `await expect(a).toHaveText("750 g");\n    await expect(b).toHaveText("$1.04");`, new_string: `await expect(b).toHaveText("$1.04");` })],
  [2, "Edit hook: changes a value", hook("Edit", { file_path: "/x/tests/b.spec.ts", old_string: `toHaveText("$1.04")`, new_string: `toHaveText("$1.05")` })],
  [0, "Edit hook: changes a locator", hook("Edit", { file_path: "/x/tests/s.spec.ts", old_string: `{ name: "Book slot" }`, new_string: `{ name: "Reserve" }` })],
  [0, "Edit hook: non-test file", hook("Edit", { file_path: "/x/src/a.ts", old_string: `expect(a)`, new_string: `` })],
  [2, "Write hook: changes a value vs disk", hook("Write", { file_path: slotsFile, content: slots.replace(`($2.99)")`, `($4.99)")`) })],
  [2, "Write hook: drops an expect vs disk", hook("Write", { file_path: slotsFile, content: slots.replace("await expect(page).toHaveURL(/\\/basket/);", "") })],
  [0, "Write hook: changes a locator vs disk", hook("Write", { file_path: slotsFile, content: slots.replace("Book slot", "Reserve") })],
  [0, "Write hook: new test file", hook("Write", { file_path: "/x/tests/new.spec.ts", content: `test("a", () => expect(1).toBe(1));` })],
];

for (const [want, name, input] of cases) {
  test(`${want ? "rejects" : "accepts"}: ${name}`, async () => {
    const p = Bun.spawnSync(["bun", `${dir}/guard.ts`], { stdin: Buffer.from(await input) });
    expect({ exit: p.exitCode, stderr: p.stderr.toString() }).toMatchObject({ exit: want });
  });
}

